### File 2 — `pkg/compactor/split_merge_planner.go` — **The only concrete `Planner` implementation**

**Current** (full file, 51 lines):
```go
// SPDX-License-Identifier: AGPL-3.0-only

package compactor

import (
    "context"
    "fmt"

    "github.com/grafana/mimir/pkg/storage/tsdb/block"
)

type SplitAndMergePlanner struct {
    ranges []int64
}

func NewSplitAndMergePlanner(ranges []int64) *SplitAndMergePlanner {
    return &SplitAndMergePlanner{
        ranges: ranges,
    }
}

// Plan implements compact.Planner.
func (c *SplitAndMergePlanner) Plan(_ context.Context, metasByMinTime []*block.Meta) ([]*block.Meta, error) {
    // The split-and-merge grouper creates single groups of blocks that are expected to be
    // compacted together, so there's no real planning to do here (reason why this function is
    // just a pass-through). However, we want to run extra checks before proceeding.
    if len(metasByMinTime) == 0 {
        return metasByMinTime, nil
    }

    // Ensure all blocks fits within the largest range. This is a double check
    // to ensure there's no bug in the previous blocks grouping, given this Plan()
    // is just a pass-through.
    largestRange := c.ranges[len(c.ranges)-1]
    rangeStart := getRangeStart(metasByMinTime[0], largestRange)
    rangeEnd := rangeStart + largestRange

    for _, b := range metasByMinTime {
        if b.MinTime < rangeStart || b.MaxTime > rangeEnd {
            return nil, fmt.Errorf("block %s with time range %d:%d is outside the largest expected range %d:%d",
                b.ULID.String(),
                b.MinTime,
                b.MaxTime,
                rangeStart,
                rangeEnd)
        }
    }

    return metasByMinTime, nil
}
```

**Change:** Add `PlanWithFilter` by extracting the core validation logic into a helper and delegating from both methods:

```go
// SPDX-License-Identifier: AGPL-3.0-only

package compactor

import (
    "context"
    "fmt"

    "github.com/grafana/mimir/pkg/storage/tsdb/block"
)

type SplitAndMergePlanner struct {
    ranges []int64
}

func NewSplitAndMergePlanner(ranges []int64) *SplitAndMergePlanner {
    return &SplitAndMergePlanner{
        ranges: ranges,
    }
}

// Plan implements Planner.
func (c *SplitAndMergePlanner) Plan(ctx context.Context, metasByMinTime []*block.Meta) ([]*block.Meta, error) {
    return c.PlanWithFilter(ctx, metasByMinTime, nil)
}

// PlanWithFilter implements Planner.
// It applies the optional filter before planning: blocks for which filter returns false are
// excluded from the candidate set. A nil filter is equivalent to accepting all blocks.
func (c *SplitAndMergePlanner) PlanWithFilter(_ context.Context, metasByMinTime []*block.Meta, filter func(*block.Meta) bool) ([]*block.Meta, error) {
    // Apply the filter first, keeping only blocks the caller wants to consider.
    filtered := metasByMinTime
    if filter != nil {
        filtered = make([]*block.Meta, 0, len(metasByMinTime))
        for _, b := range metasByMinTime {
            if filter(b) {
                filtered = append(filtered, b)
            }
        }
    }

    // The split-and-merge grouper creates single groups of blocks that are expected to be
    // compacted together, so there's no real planning to do here (reason why this function is
    // just a pass-through). However, we want to run extra checks before proceeding.
    if len(filtered) == 0 {
        return filtered, nil
    }

    // Ensure all blocks fit within the largest range. This is a double check
    // to ensure there's no bug in the previous blocks grouping, given this Plan()
    // is just a pass-through.
    largestRange := c.ranges[len(c.ranges)-1]
    rangeStart := getRangeStart(filtered[0], largestRange)
    rangeEnd := rangeStart + largestRange

    for _, b := range filtered {
        if b.MinTime < rangeStart || b.MaxTime > rangeEnd {
            return nil, fmt.Errorf("block %s with time range %d:%d is outside the largest expected range %d:%d",
                b.ULID.String(),
                b.MinTime,
                b.MaxTime,
                rangeStart,
                rangeEnd)
        }
    }

    return filtered, nil
}
```

> **Key design decisions:**
> - `Plan` now delegates to `PlanWithFilter(ctx, metasByMinTime, nil)` — zero code duplication, existing behaviour is 100% preserved.
> - `filter == nil` means "accept all", so the nil-filter path is identical to the old `Plan` body.
> - The filtered slice is built before the range-start anchor is computed from `filtered[0]`, which is correct: the anchor must come from the first *accepted* block, not the first block in the original slice.

---

### File 3 — `pkg/compactor/split_merge_planner_test.go` — **Unit tests for `SplitAndMergePlanner`**

The existing `TestSplitAndMergePlanner_Plan` tests call `c.Plan(...)` directly. They continue to pass unchanged because `Plan` now delegates to `PlanWithFilter`. Add a new test function for `PlanWithFilter`:

```go
func TestSplitAndMergePlanner_PlanWithFilter(t *testing.T) {
    block1 := ulid.MustNew(1, nil)
    block2 := ulid.MustNew(2, nil)
    block3 := ulid.MustNew(3, nil)

    tests := map[string]struct {
        ranges          []int64
        blocksByMinTime []*block.Meta
        filter          func(*block.Meta) bool
        expectedBlocks  []*block.Meta
        expectedErr     error
    }{
        "nil filter behaves like Plan": {
            ranges: []int64{20, 40, 60},
            blocksByMinTime: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block2, MinTime: 20, MaxTime: 40, Version: block.TSDBVersion1}},
            },
            filter: nil,
            expectedBlocks: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block2, MinTime: 20, MaxTime: 40, Version: block.TSDBVersion1}},
            },
        },
        "filter excludes one block": {
            ranges: []int64{20, 40, 60},
            blocksByMinTime: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block2, MinTime: 20, MaxTime: 40, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block3, MinTime: 40, MaxTime: 60, Version: block.TSDBVersion1}},
            },
            // Exclude block2.
            filter: func(m *block.Meta) bool { return m.ULID != block2 },
            expectedBlocks: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block3, MinTime: 40, MaxTime: 60, Version: block.TSDBVersion1}},
            },
        },
        "filter excludes all blocks returns empty": {
            ranges:          []int64{20, 40, 60},
            blocksByMinTime: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
            },
            filter:         func(*block.Meta) bool { return false },
            expectedBlocks: []*block.Meta{},
        },
        "filter keeps block outside range returns error": {
            ranges: []int64{20, 40, 60},
            blocksByMinTime: []*block.Meta{
                {BlockMeta: tsdb.BlockMeta{ULID: block1, MinTime: 0, MaxTime: 20, Version: block.TSDBVersion1}},
                {BlockMeta: tsdb.BlockMeta{ULID: block2, MinTime: 10, MaxTime: 80, Version: block.TSDBVersion1}},
            },
            filter:      func(*block.Meta) bool { return true }, // keep all
            expectedErr: fmt.Errorf("block %s with time range 10:80 is outside the largest expected range 0:60", block2.String()),
        },
    }

    for testName, testData := range tests {
        t.Run(testName, func(t *testing.T) {
            c := NewSplitAndMergePlanner(testData.ranges)
            actual, err := c.PlanWithFilter(context.Background(), testData.blocksByMinTime, testData.filter)
            assert.Equal(t, testData.expectedErr, err)
            if testData.expectedErr == nil {
                assert.Equal(t, testData.expectedBlocks, actual)
            }
        })
    }
}
```

